#!/bin/bash
# ============================================
# GitHub Projects Sync Wizard - one-click install script
#
# ⚠️ Organization Projects only
#    (User Projects are not supported due to GitHub API limits)
#
# ⚠️ Prerequisites:
#   - Node.js 18.0.0 or later (check with node -v)
#   - npm (installed with Node.js)
#   - Cloudflare account
#
# Usage (command generated by the wizard):
# curl -fsSL https://raw.githubusercontent.com/.../projects-sync-wizard-setup.sh | bash -s -- \
#   --owner "ORG_NAME" \
#   --project "1" \
#   --worker-name "my-worker" \
#   --webhook-secret "abc123" \
#   --github-token "ghp_xxxx..." \
#   --labels "작업전,작업중,작업완료"
# ============================================

set -e

# Color definitions
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m'

# Defaults (Organization Projects only)
OWNER_NAME=""
PROJECT_NUMBER=""
WORKER_NAME="github-projects-sync-worker"
WEBHOOK_SECRET=""
STATUS_LABELS=""
GITHUB_TOKEN=""
WORK_DIR=""

# Automatic temp directory cleanup
cleanup_on_exit() {
    local exit_code=$?
    if [ -n "$WORK_DIR" ] && [ -d "$WORK_DIR" ]; then
        echo ""
        echo -e "${YELLOW}🧹 Cleaning up the temp directory...${NC}"
        cd ~ 2>/dev/null || cd /tmp
        rm -rf "$WORK_DIR" 2>/dev/null || true
        echo -e "${GREEN}✅ Temp directory deleted${NC}"
    fi
    exit $exit_code
}

# Clean up automatically on exit (normal exit, error and interrupt)
trap cleanup_on_exit EXIT ERR INT TERM

# Argument parsing (Organization Projects only)
while [[ $# -gt 0 ]]; do
    case $1 in
        --owner)
            OWNER_NAME="$2"
            shift 2
            ;;
        --project)
            PROJECT_NUMBER="$2"
            shift 2
            ;;
        --worker-name)
            WORKER_NAME="$2"
            shift 2
            ;;
        --webhook-secret)
            WEBHOOK_SECRET="$2"
            shift 2
            ;;
        --labels)
            STATUS_LABELS="$2"
            shift 2
            ;;
        --github-token)
            GITHUB_TOKEN="$2"
            shift 2
            ;;
        --type)
            # Backward compatibility: the --type option is ignored (Organization only)
            shift 2
            ;;
        --repo-owner|--repo-name)
            # Backward compatibility: User-related options are ignored
            shift 2
            ;;
        *)
            echo -e "${RED}Unknown option: $1${NC}"
            exit 1
            ;;
    esac
done

# Check required arguments
if [ -z "$OWNER_NAME" ] || [ -z "$PROJECT_NUMBER" ] || [ -z "$WEBHOOK_SECRET" ] || [ -z "$GITHUB_TOKEN" ]; then
    echo -e "${RED}❌ Required arguments are missing.${NC}"
    echo "Required: --owner, --project, --webhook-secret, --github-token"
    exit 1
fi

# Make the Worker name follow Cloudflare rules (lowercase letters, digits, hyphens only)
WORKER_NAME=$(echo "$WORKER_NAME" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9-]/-/g' | sed 's/-\+/-/g' | sed 's/^-\|-$//g')

# Check the Node.js version
echo ""
echo -e "${CYAN}🔍 Checking prerequisites...${NC}"

if ! command -v node &> /dev/null; then
    echo -e "${RED}❌ Node.js is not installed.${NC}"
    echo -e "   Install Node.js 18 or later from https://nodejs.org."
    exit 1
fi

NODE_VERSION=$(node -v | cut -d'v' -f2 | cut -d'.' -f1)
if [ "$NODE_VERSION" -lt 18 ]; then
    echo -e "${RED}❌ Node.js 18 or later is required. Current version: $(node -v)${NC}"
    exit 1
fi
echo -e "${GREEN}✅ Node.js $(node -v)${NC}"

if ! command -v npm &> /dev/null; then
    echo -e "${RED}❌ npm is not installed.${NC}"
    exit 1
fi
echo -e "${GREEN}✅ npm $(npm -v)${NC}"

if ! command -v jq &> /dev/null; then
    echo -e "${YELLOW}⚠️  jq is not installed. Installing...${NC}"
    if [[ "$OSTYPE" == "darwin"* ]]; then
        brew install jq 2>/dev/null || {
            echo -e "${RED}❌ Failed to install jq. Install it manually with brew install jq.${NC}"
            exit 1
        }
    else
        sudo apt-get install -y jq 2>/dev/null || sudo yum install -y jq 2>/dev/null || {
            echo -e "${RED}❌ Failed to install jq. Install it manually.${NC}"
            exit 1
        }
    fi
fi
echo -e "${GREEN}✅ jq $(jq --version)${NC}"

echo ""
echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo -e "${CYAN}   🔄 GitHub Projects Sync Worker one-click install${NC}"
echo -e "${CYAN}   (Organization Projects only)${NC}"
echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo ""
echo -e "${BLUE}📋 Settings:${NC}"
echo -e "   Organization: ${GREEN}$OWNER_NAME${NC}"
echo -e "   Project #: ${GREEN}$PROJECT_NUMBER${NC}"
echo -e "   Worker name: ${GREEN}$WORKER_NAME${NC}"
echo ""

# Create the temp directory
WORK_DIR=$(mktemp -d)
cd "$WORK_DIR"
echo -e "${YELLOW}[1/5]${NC} 📁 Work directory: $WORK_DIR"

# Convert labels to a JSON array (compact - one line)
IFS=',' read -ra LABEL_ARRAY <<< "$STATUS_LABELS"
LABELS_JSON=$(printf '%s\n' "${LABEL_ARRAY[@]}" | jq -R . | jq -sc .)

# Create wrangler.toml
echo -e "${YELLOW}[2/5]${NC} 📝 Creating config files..."
cat > wrangler.toml << EOF
name = "$WORKER_NAME"
main = "src/index.ts"
compatibility_date = "2024-01-01"

[vars]
PROJECT_NUMBER = "$PROJECT_NUMBER"
STATUS_FIELD = "Status"
STATUS_LABELS = '$LABELS_JSON'
ORG_NAME = "$OWNER_NAME"
EOF

# Create package.json
cat > package.json << 'PACKAGE_EOF'
{
  "name": "github-projects-sync-worker",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "deploy": "wrangler deploy",
    "dev": "wrangler dev",
    "tail": "wrangler tail"
  },
  "devDependencies": {
    "@cloudflare/workers-types": "^4.20240117.0",
    "typescript": "^5.3.3",
    "wrangler": "^3.22.1"
  }
}
PACKAGE_EOF

# Create tsconfig.json
cat > tsconfig.json << 'TSCONFIG_EOF'
{
  "compilerOptions": {
    "target": "ES2021",
    "module": "ESNext",
    "moduleResolution": "node",
    "lib": ["ES2021"],
    "types": ["@cloudflare/workers-types"],
    "strict": true,
    "noEmit": true,
    "skipLibCheck": true
  },
  "include": ["src/**/*"]
}
TSCONFIG_EOF

# Create the Worker code
mkdir -p src
cat > src/index.ts << 'WORKER_EOF'
/**
 * GitHub Projects Sync Worker
 * Projects Status → Issue Label sync
 */

export interface Env {
  GITHUB_TOKEN: string;
  WEBHOOK_SECRET: string;
  PROJECT_NUMBER: string;
  STATUS_FIELD: string;
  STATUS_LABELS: string;
  ORG_NAME: string;
}

interface GitHubWebhookPayload {
  action: string;
  projects_v2_item?: {
    id: number;
    node_id: string;
    content_node_id: string;
    content_type: string;
  };
  changes?: {
    field_value?: {
      field_node_id: string;
      field_type: string;
    };
  };
  organization?: {
    login: string;
  };
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    if (request.method === 'GET') {
      return new Response(JSON.stringify({
        status: 'ok',
        message: 'GitHub Projects Sync Worker is running',
        org: env.ORG_NAME,
        project: env.PROJECT_NUMBER
      }), {
        headers: { 'Content-Type': 'application/json' }
      });
    }

    if (request.method !== 'POST') {
      return new Response('Method Not Allowed', { status: 405 });
    }

    try {
      const signature = request.headers.get('X-Hub-Signature-256');
      const body = await request.text();

      if (!await verifySignature(body, signature, env.WEBHOOK_SECRET)) {
        console.log('Invalid signature');
        return new Response('Unauthorized', { status: 401 });
      }

      const payload: GitHubWebhookPayload = JSON.parse(body);

      if (payload.action !== 'edited' || !payload.projects_v2_item) {
        return new Response('Ignored', { status: 200 });
      }

      if (payload.projects_v2_item.content_type !== 'Issue' &&
          payload.projects_v2_item.content_type !== 'PullRequest') {
        return new Response('Not an Issue or PR', { status: 200 });
      }

      const contentNodeId = payload.projects_v2_item.content_node_id;
      const statusLabels: string[] = JSON.parse(env.STATUS_LABELS);

      const status = await getCurrentStatus(
        contentNodeId,
        parseInt(env.PROJECT_NUMBER),
        env.STATUS_FIELD,
        env.GITHUB_TOKEN
      );

      if (!status) {
        console.log('Status not found');
        return new Response('Status not found', { status: 200 });
      }

      console.log(`Current status: ${status}`);

      if (!statusLabels.includes(status)) {
        console.log(`Status "${status}" not in label list`);
        return new Response('Status not in label list', { status: 200 });
      }

      await syncLabel(contentNodeId, status, statusLabels, env.GITHUB_TOKEN);

      return new Response('OK', { status: 200 });
    } catch (error) {
      console.error('Error:', error);
      return new Response(`Error: ${error}`, { status: 500 });
    }
  }
};

async function verifySignature(
  payload: string,
  signature: string | null,
  secret: string
): Promise<boolean> {
  if (!signature) return false;

  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );

  const signatureBuffer = await crypto.subtle.sign(
    'HMAC',
    key,
    encoder.encode(payload)
  );

  const expectedSignature = 'sha256=' + Array.from(new Uint8Array(signatureBuffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');

  return signature === expectedSignature;
}

async function getCurrentStatus(
  contentNodeId: string,
  projectNumber: number,
  statusField: string,
  token: string
): Promise<string | null> {
  const query = `
    query($nodeId: ID!) {
      node(id: $nodeId) {
        ... on Issue {
          projectItems(first: 10) {
            nodes {
              project {
                number
              }
              fieldValueByName(name: "${statusField}") {
                ... on ProjectV2ItemFieldSingleSelectValue {
                  name
                }
              }
            }
          }
        }
        ... on PullRequest {
          projectItems(first: 10) {
            nodes {
              project {
                number
              }
              fieldValueByName(name: "${statusField}") {
                ... on ProjectV2ItemFieldSingleSelectValue {
                  name
                }
              }
            }
          }
        }
      }
    }
  `;

  const response = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'User-Agent': 'GitHub-Projects-Sync-Worker'
    },
    body: JSON.stringify({ query, variables: { nodeId: contentNodeId } })
  });

  const data = await response.json() as any;

  const items = data.data?.node?.projectItems?.nodes || [];
  const targetItem = items.find((item: any) => item.project?.number === projectNumber);

  return targetItem?.fieldValueByName?.name || null;
}

async function syncLabel(
  contentNodeId: string,
  newStatus: string,
  statusLabels: string[],
  token: string
): Promise<void> {
  const infoQuery = `
    query($nodeId: ID!) {
      node(id: $nodeId) {
        ... on Issue {
          number
          repository {
            owner { login }
            name
          }
          labels(first: 100) {
            nodes { name }
          }
        }
        ... on PullRequest {
          number
          repository {
            owner { login }
            name
          }
          labels(first: 100) {
            nodes { name }
          }
        }
      }
    }
  `;

  const infoResponse = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'User-Agent': 'GitHub-Projects-Sync-Worker'
    },
    body: JSON.stringify({ query: infoQuery, variables: { nodeId: contentNodeId } })
  });

  const infoData = await infoResponse.json() as any;
  const node = infoData.data?.node;

  if (!node) {
    console.log('Node not found');
    return;
  }

  const owner = node.repository.owner.login;
  const repo = node.repository.name;
  const issueNumber = node.number;
  const currentLabels = node.labels.nodes.map((l: any) => l.name);

  console.log(`Issue: ${owner}/${repo}#${issueNumber}`);
  console.log(`Current labels: ${currentLabels.join(', ')}`);

  const currentStatusLabel = currentLabels.find((l: string) => statusLabels.includes(l));

  if (currentStatusLabel === newStatus) {
    console.log(`Label already set to "${newStatus}", skipping`);
    return;
  }

  if (currentStatusLabel) {
    await removeLabel(owner, repo, issueNumber, currentStatusLabel, token);
  }

  await addLabel(owner, repo, issueNumber, newStatus, token);

  console.log(`Label updated to "${newStatus}"`);
}

async function removeLabel(
  owner: string,
  repo: string,
  issueNumber: number,
  label: string,
  token: string
): Promise<void> {
  const url = `https://api.github.com/repos/${owner}/${repo}/issues/${issueNumber}/labels/${encodeURIComponent(label)}`;

  await fetch(url, {
    method: 'DELETE',
    headers: {
      'Authorization': `Bearer ${token}`,
      'User-Agent': 'GitHub-Projects-Sync-Worker'
    }
  });
}

async function addLabel(
  owner: string,
  repo: string,
  issueNumber: number,
  label: string,
  token: string
): Promise<void> {
  const url = `https://api.github.com/repos/${owner}/${repo}/issues/${issueNumber}/labels`;

  await fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'User-Agent': 'GitHub-Projects-Sync-Worker'
    },
    body: JSON.stringify({ labels: [label] })
  });
}
WORKER_EOF

echo -e "${GREEN}✅ Config files created${NC}"

# npm install
echo -e "${YELLOW}[3/5]${NC} 📦 Installing dependencies..."
npm config set strict-ssl false 2>/dev/null || true
npm install --silent && echo -e "${GREEN}✅ Dependencies installed${NC}" || {
    echo -e "${RED}❌ npm install failed${NC}"
    exit 1
}
npm config set strict-ssl true 2>/dev/null || true

# Cloudflare login
echo -e "${YELLOW}[4/5]${NC} 🔐 Logging in to Cloudflare..."
export NODE_TLS_REJECT_UNAUTHORIZED=0
npx wrangler login && echo -e "${GREEN}✅ Cloudflare login done${NC}" || {
    echo -e "${RED}❌ Login failed${NC}"
    exit 1
}

# Deploy the Worker
echo -e "${YELLOW}[5/5]${NC} 🚀 Deploying the Worker..."
DEPLOY_SUCCESS=false
WORKER_URL=""

while [ "$DEPLOY_SUCCESS" = false ]; do
    DEPLOY_OUTPUT=$(npx wrangler deploy 2>&1) || true

    if echo "$DEPLOY_OUTPUT" | grep -q "https://.*workers.dev"; then
        WORKER_URL=$(echo "$DEPLOY_OUTPUT" | grep -o 'https://[^[:space:]]*workers.dev' | head -1)
        DEPLOY_SUCCESS=true
        echo -e "${GREEN}✅ Worker deployed${NC}"
    else
        echo -e "${RED}❌ Worker deploy failed${NC}"
        echo "$DEPLOY_OUTPUT" | tail -5
        echo ""
        echo -e "Enter a new Worker name (q to quit):"
        read -r NEW_NAME
        [ "$NEW_NAME" = "q" ] && exit 1
        if [ -n "$NEW_NAME" ]; then
            if [[ "$OSTYPE" == "darwin"* ]]; then
                sed -i '' "s/^name = \".*\"/name = \"$NEW_NAME\"/" wrangler.toml
            else
                sed -i "s/^name = \".*\"/name = \"$NEW_NAME\"/" wrangler.toml
            fi
        fi
    fi
done

# Secrets (values passed as arguments, via pipe)
echo ""
echo -e "${CYAN}🔑 Setting Secrets${NC}"
echo -e "${YELLOW}Setting GITHUB_TOKEN...${NC}"
echo "$GITHUB_TOKEN" | npx wrangler secret put GITHUB_TOKEN 2>/dev/null && echo -e "${GREEN}✅ GITHUB_TOKEN set${NC}" || {
    echo -e "${RED}❌ Failed to set GITHUB_TOKEN${NC}"
    exit 1
}
echo -e "${YELLOW}Setting WEBHOOK_SECRET...${NC}"
echo "$WEBHOOK_SECRET" | npx wrangler secret put WEBHOOK_SECRET 2>/dev/null && echo -e "${GREEN}✅ WEBHOOK_SECRET set${NC}" || {
    echo -e "${RED}❌ Failed to set WEBHOOK_SECRET${NC}"
    exit 1
}

# Webhook URL (Organization webhooks only) - /new goes straight to the creation page
WEBHOOK_SETTINGS_URL="https://github.com/organizations/$OWNER_NAME/settings/hooks/new"

echo ""
echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo -e "${GREEN}🎉 Install complete!${NC}"
echo ""
echo -e "📌 ${BLUE}Worker URL:${NC} ${CYAN}$WORKER_URL${NC}"
echo ""
echo -e "${BLUE}📋 Next step: set up the GitHub Webhook${NC}"
echo -e "   1. Open the webhook creation page:"
echo -e "      ${CYAN}$WEBHOOK_SETTINGS_URL${NC}"
echo -e "   2. Enter the settings:"
echo -e "      - Payload URL: ${CYAN}$WORKER_URL${NC}"
echo -e "      - Content type: application/json"
echo -e "      - Secret: ${CYAN}$WEBHOOK_SECRET${NC}"
echo -e "   3. Events: 'Let me select individual events' → choose ${GREEN}'Project v2 items'${NC}"
echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"

# The work directory is cleaned up automatically by trap
